/**
 * Standalone Bundled Code Syntax Highlighter for Cognitive Coach Webview.
 * Highlights Python, JavaScript, C++, Java syntax offline.
 */
(function(global) {
  'use strict';

  const KEYWORDS = new Set([
    'def', 'return', 'if', 'else', 'elif', 'for', 'while', 'in', 'import', 'from', 'as',
    'class', 'try', 'except', 'finally', 'with', 'lambda', 'pass', 'break', 'continue',
    'const', 'let', 'var', 'function', 'async', 'await', 'public', 'private', 'static',
    'int', 'float', 'double', 'char', 'void', 'bool', 'boolean', 'true', 'false', 'null',
    'None', 'True', 'False', 'self', 'new', 'this'
  ]);

  function highlightCode(codeText) {
    if (!codeText) return '';

    // Tokens: Strings, Comments, Numbers, Words
    const tokenRegex = /(".*?"|'.*?'|#.*$|\/\/.*$|\b\d+\b|\b[a-zA-Z_]\w*\b)/gm;

    return codeText.replace(tokenRegex, function(match) {
      if (match.startsWith('#') || match.startsWith('//')) {
        return '<span class="hljs-comment">' + match + '</span>';
      }
      if ((match.startsWith('"') && match.endsWith('"')) || (match.startsWith("'") && match.endsWith("'"))) {
        return '<span class="hljs-string">' + match + '</span>';
      }
      if (/^\d+$/.test(match)) {
        return '<span class="hljs-number">' + match + '</span>';
      }
      if (KEYWORDS.has(match)) {
        return '<span class="hljs-keyword">' + match + '</span>';
      }
      return match;
    });
  }

  function highlightElement(el) {
    if (!el) return;
    el.innerHTML = highlightCode(el.textContent);
  }

  global.hljs = {
    highlightElement: highlightElement,
    highlightCode: highlightCode
  };
})(typeof window !== 'undefined' ? window : this);
